def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], weight_lst: np.ndarray, value1_lst: np.ndarray, value2_lst: np.ndarray, capacity: float) -> np.ndarray:
    """
    Select a promising solution from the archive and generate a neighbor solution from it.

    Args:
    archive: List of (solution, objective) pairs. Each solution is a binary numpy array (0/1) of item selections.
             Each objective is a tuple of two float values (total value1, total value2).
    weight_lst: Numpy array of shape (N, ), item weights.
    value1_lst: Numpy array of shape (N, ), item values for objective 1.
    value2_lst: Numpy array of shape (N, ), item values for objective 2.
    capacity: Maximum allowed total weight.

    Returns:
    A new neighbor solution (numpy array).
    """
    if not archive:
        return np.zeros_like(weight_lst, dtype=int)

    # Step 1: Select the most promising solution using crowding distance
    def crowding_distance(solutions):
        if len(solutions) < 3:
            return [0.0] * len(solutions)
        distances = [0.0] * len(solutions)
        for obj_idx in range(2):
            sorted_idx = np.argsort([obj[obj_idx] for _, obj in solutions])
            min_val = solutions[sorted_idx[0]][1][obj_idx]
            max_val = solutions[sorted_idx[-1]][1][obj_idx]
            if max_val == min_val:
                continue
            distances[sorted_idx[0]] = np.inf
            distances[sorted_idx[-1]] = np.inf
            for i in range(1, len(solutions) - 1):
                distances[sorted_idx[i]] += (solutions[sorted_idx[i+1]][1][obj_idx] - solutions[sorted_idx[i-1]][1][obj_idx]) / (max_val - min_val)
        return distances

    distances = crowding_distance(archive)
    selected_idx = np.argmax(distances)
    base_solution, _ = archive[selected_idx]
    new_solution = base_solution.copy()
    current_weight = np.sum(weight_lst[new_solution == 1])

    # Step 2: Apply multi-phase perturbation strategy
    n_items = len(weight_lst)
    perturbation_phases = 3  # Number of perturbation phases
    phase_intensity = [0.2, 0.1, 0.05]  # Decreasing perturbation intensity

    for phase in range(perturbation_phases):
        # Phase 1: Targeted item flips based on marginal contribution
        if phase == 0:
            # Calculate marginal contributions
            marginal_value1 = value1_lst / weight_lst
            marginal_value2 = value2_lst / weight_lst
            marginal_scores = marginal_value1 + marginal_value2

            # Sort items by marginal score
            sorted_indices = np.argsort(marginal_scores)[::-1]

            # Flip top k% items with probability phase_intensity[phase]
            k = int(n_items * phase_intensity[phase])
            for i in sorted_indices[:k]:
                if np.random.rand() < phase_intensity[phase]:
                    if new_solution[i] == 1:
                        if current_weight - weight_lst[i] >= 0:
                            new_solution[i] = 0
                            current_weight -= weight_lst[i]
                    else:
                        if current_weight + weight_lst[i] <= capacity:
                            new_solution[i] = 1
                            current_weight += weight_lst[i]

        # Phase 2: Random walk with decreasing step size
        elif phase == 1:
            for i in range(n_items):
                if np.random.rand() < phase_intensity[phase]:
                    if new_solution[i] == 1:
                        if current_weight - weight_lst[i] >= 0:
                            new_solution[i] = 0
                            current_weight -= weight_lst[i]
                    else:
                        if current_weight + weight_lst[i] <= capacity:
                            new_solution[i] = 1
                            current_weight += weight_lst[i]

        # Phase 3: Greedy improvement with decreasing intensity
        else:
            # Evaluate all possible single-item swaps
            best_delta = 0
            best_item = -1
            best_action = None

            for i in range(n_items):
                if new_solution[i] == 1:
                    # Evaluate removing item i
                    delta_weight = -weight_lst[i]
                    delta_value1 = -value1_lst[i]
                    delta_value2 = -value2_lst[i]
                    if current_weight + delta_weight <= capacity:
                        delta = 0.5 * delta_value1 + 0.5 * delta_value2
                        if delta < best_delta:
                            best_delta = delta
                            best_item = i
                            best_action = 'remove'
                else:
                    # Evaluate adding item i
                    delta_weight = weight_lst[i]
                    delta_value1 = value1_lst[i]
                    delta_value2 = value2_lst[i]
                    if current_weight + delta_weight <= capacity:
                        delta = 0.5 * delta_value1 + 0.5 * delta_value2
                        if delta > best_delta:
                            best_delta = delta
                            best_item = i
                            best_action = 'add'

            if best_item != -1 and np.random.rand() < phase_intensity[phase]:
                if best_action == 'add':
                    new_solution[best_item] = 1
                    current_weight += weight_lst[best_item]
                else:
                    new_solution[best_item] = 0
                    current_weight -= weight_lst[best_item]

    return new_solution

