def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], weight_lst: np.ndarray, value1_lst: np.ndarray, value2_lst: np.ndarray, capacity: float) -> np.ndarray:
    """
    Select a promising solution from the archive and generate a neighbor solution from it.

    Args:
    archive: List of (solution, objective) pairs. Each solution is a binary numpy array (0/1) of item selections.
             Each objective is a tuple of two float values (total value1, total value2).
    weight_lst: Numpy array of shape (N, ), item weights.
    value1_lst: Numpy array of shape (N, ), item values for objective 1.
    value2_lst: Numpy array of shape (N, ), item values for objective 2.
    capacity: Maximum allowed total weight.

    Returns:
    A new neighbor solution (numpy array).
    """
    if not archive:
        raise ValueError("Archive is empty")

    # Step 1: Identify the most underrepresented objective in the archive
    all_values1 = [obj[0] for _, obj in archive]
    all_values2 = [obj[1] for _, obj in archive]
    mean_value1 = np.mean(all_values1)
    mean_value2 = np.mean(all_values2)

    # Select the objective that needs more improvement
    if mean_value1 < mean_value2:
        target_obj = 1  # Focus on value1
    else:
        target_obj = 2  # Focus on value2

    # Step 2: Select a base solution with high potential for improvement in the target objective
    # Calculate potential improvement for each solution
    potential = []
    for sol, (v1, v2) in archive:
        if target_obj == 1:
            potential.append(v1 / (v1 + v2 + 1e-6))
        else:
            potential.append(v2 / (v1 + v2 + 1e-6))
    selected_idx = np.argmax(potential)
    base_solution = archive[selected_idx][0].copy()
    new_solution = base_solution.copy()

    # Step 3: Calculate current total weight and remaining capacity
    current_weight = np.sum(weight_lst * new_solution)
    remaining_capacity = capacity - current_weight

    # Step 4: Generate candidate items to flip (add or remove)
    candidates = []
    for i in range(len(new_solution)):
        if new_solution[i] == 1:
            # Consider removing item i if it's not critical for the target objective
            if target_obj == 1 and value1_lst[i] < mean_value1:
                candidates.append((i, -1))
            elif target_obj == 2 and value2_lst[i] < mean_value2:
                candidates.append((i, -1))
        else:
            # Consider adding item i if it fits and improves the target objective
            if weight_lst[i] <= remaining_capacity:
                if target_obj == 1 and value1_lst[i] > mean_value1:
                    candidates.append((i, 1))
                elif target_obj == 2 and value2_lst[i] > mean_value2:
                    candidates.append((i, 1))

    if not candidates:
        return base_solution.copy()

    # Step 5: Select the best candidate based on adaptive weight mechanism
    best_candidate = None
    best_score = -np.inf
    for candidate in candidates:
        idx, flip = candidate
        if flip == 1:
            # Adding an item: prioritize based on target objective and its contribution
            if target_obj == 1:
                score = value1_lst[idx] / (1 + weight_lst[idx])
            else:
                score = value2_lst[idx] / (1 + weight_lst[idx])
        else:
            # Removing an item: prioritize based on the other objective's value
            if target_obj == 1:
                score = -value2_lst[idx] / (1 + weight_lst[idx])
            else:
                score = -value1_lst[idx] / (1 + weight_lst[idx])

        if score > best_score:
            best_score = score
            best_candidate = candidate

    if best_candidate is None:
        return base_solution.copy()

    # Step 6: Apply the selected flip
    idx, flip = best_candidate
    new_solution[idx] = 1 if flip == 1 else 0

    # Step 7: Ensure feasibility (shouldn't be needed due to checks above)
    if np.sum(weight_lst * new_solution) > capacity:
        # If not feasible, remove items randomly until feasible
        while np.sum(weight_lst * new_solution) > capacity:
            in_solution = np.where(new_solution == 1)[0]
            if len(in_solution) == 0:
                break
            item_to_remove = np.random.choice(in_solution)
            new_solution[item_to_remove] = 0

    return new_solution

